	local gametop = gModuleMgr.getObject("gametop")
	local backpackCtrl = gametop.playertop_:getModule("backpackCtrl")
	local canAwake = false
	if awakeInfo then
		canAwake = awakeInfo.itemCount <= backpackCtrl:getItemCount(awakeInfo.item)
	end
	return canAwake
end
