	if 0 ~= mID then
		_ENV = nil
		;(nil).cmd = gCmd.CMD_ACHIEVEMENT_MODULE
		_ENV, (nil).subcmd = gCmd.REQ_ACHIEVEMENT_REWARD, gCmd.REQ_ACHIEVEMENT_REWARD
		;(nil).data, gCmd.REQ_ACHIEVEMENT_REWARD.id = gCmd.REQ_ACHIEVEMENT_REWARD, mID
