	print("godArmsRuneCtrl:sendInit()=======")
	_ENV = nil
	serverproxy:Request(gCmd.CMD_GOD_ARMS_RUNE_MODULE, gCmd.REQ_GOD_ARMS_RUNE_INIT, nil)
end
