function kingdomMapCtrl:isForbitWar()
	local forbid = self:getForbitWarBeginTime() <= 0 and 0 < self:getForbitWarLeftTime()
	if forbid then
		if worldMapDefine.isInRemains() then
			return false
		end
		if worldMapDefine.isInPyramid() then
			return false
		end
	end
	return forbid
end
